draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // Draw leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 - 30, H/2 - 70, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 - 70, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();

  // Draw stick figure
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 100, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 80, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 120, H/2 + 80);
  ctx.stroke();

  // Animate stick figure
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100);
  ctx.lineTo(W/2 + 100 + Math.sin(t) * 20, H/2 + 120);
  ctx.stroke();

  ctx.restore();
}
